<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
require_permission('wastage.create');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$product=(int)($_POST['product_id']??0);$branch=(int)($_POST['branch_id']??0);$brand=(int)($_POST['brand_id']??0);$qty=(float)($_POST['quantity']??0);$date=$_POST['date']??date('Y-m-d');$reason=trim($_POST['reason']??'Other');$notes=trim($_POST['notes']??'');
    if(!$product||!$branch||!$brand||$qty<=0){flash('error','Choose a product and enter a valid wastage quantity.');redirect('wastage.php');}
    try{
        enforce_branch_scope($branch);$pdo->beginTransaction();
        $p=$pdo->prepare('SELECT p.name,u.symbol FROM products p JOIN units u ON u.id=p.unit_id WHERE p.id=? AND p.status="active" AND p.deleted_at IS NULL FOR UPDATE');$p->execute([$product]);$item=$p->fetch();if(!$item)throw new RuntimeException('The selected product is unavailable.');
        $available=stock_balance($pdo,$product,$branch,$brand);if($qty>$available)throw new RuntimeException('Only '.number_format($available,3).' '.$item['symbol'].' of '.$item['name'].' is available.');
        $ref=next_reference($pdo,'WST','wastages');$s=$pdo->prepare('INSERT INTO wastages(reference_no,wastage_date,branch_id,brand_id,reason,cost_impact,notes,created_by,approved_by) VALUES(?,?,?,?,?,0,?,?,?)');$s->execute([$ref,$date,$branch,$brand,$reason,$notes,user()['id'],user()['id']]);$id=(int)$pdo->lastInsertId();
        $pdo->prepare('INSERT INTO wastage_items(wastage_id,product_id,quantity,unit_cost) VALUES(?,?,?,0)')->execute([$id,$product,$qty]);
        ledger($pdo,['product_id'=>$product,'branch_id'=>$branch,'brand_id'=>$brand,'transaction_type'=>'wastage','reference_type'=>'wastage','reference_id'=>$id,'reference_no'=>$ref,'quantity_in'=>0,'quantity_out'=>$qty,'notes'=>$reason.($notes?' · '.$notes:'')]);
        audit($pdo,'create','wastage',$id,null,['reference'=>$ref,'product'=>$item['name'],'quantity'=>$qty,'unit'=>$item['symbol']]);$pdo->commit();
        flash('success',number_format($qty,3).' '.$item['symbol'].' of '.$item['name'].' recorded as wastage. Stock updated.');redirect('wastage.php');
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('wastage.php');}
}
$branches=options($pdo,'branches');$brands=options($pdo,'brands');$selectedBranch=(int)(user()['branch_id']??0)?:((int)($branches[0]['id']??0));$selectedBrand=(int)($brands[0]['id']??0);
$history=$pdo->query('SELECT w.reference_no,w.wastage_date,w.reason,w.notes,w.created_at,wi.quantity,p.name product,u.symbol,b.name branch,br.name brand,usr.name entered_by FROM wastages w JOIN wastage_items wi ON wi.wastage_id=w.id JOIN products p ON p.id=wi.product_id JOIN units u ON u.id=p.unit_id JOIN branches b ON b.id=w.branch_id JOIN brands br ON br.id=w.brand_id JOIN users usr ON usr.id=w.created_by WHERE w.deleted_at IS NULL ORDER BY w.id DESC LIMIT 30')->fetchAll();
$today=(int)$pdo->query('SELECT COUNT(*) FROM wastages WHERE wastage_date=CURDATE() AND deleted_at IS NULL')->fetchColumn();$productCount=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE status="active" AND deleted_at IS NULL')->fetchColumn();
render_header('Wastage','wastage');page_title('Simple Wastage Entry','FAST STOCK CONTROL','Choose the product, enter the wasted quantity and save. No pricing is required.');
?><div class="wastage-summary"><div><span>Today</span><b><?=$today?> entries</b></div><div><span>Products ready</span><b><?=$productCount?> items</b></div><div><span>Stock update</span><b>Automatic</b></div></div>
<article class="card wastage-entry"><form method="post" data-wastage-picker><?=csrf_field()?><input type="hidden" name="product_id" required>
<div class="wastage-context"><label>Branch<select name="branch_id" required><?php foreach($branches as $x):?><option value="<?=$x['id']?>"<?=selected($selectedBranch,$x['id'])?>><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Brand<select name="brand_id" required><?php foreach($brands as $x):?><option value="<?=$x['id']?>"<?=selected($selectedBrand,$x['id'])?>><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Date<input type="date" name="date" value="<?=date('Y-m-d')?>" max="<?=date('Y-m-d')?>" required></label></div>
<div class="picker-title"><div><span class="eyebrow">STEP 1</span><h2>Choose product</h2><p>Search items such as Beef, Cauliflower, Milk or Packaging.</p></div><a class="btn small" href="<?=app_url('products.php?action=create')?>"><i data-icon="plus"></i>Add Product</a></div>
<input class="product-search" data-product-search placeholder="Search product name…" autocomplete="off"><div class="product-grid" data-product-grid></div>
<div class="wastage-details"><div class="selection-summary" data-selection><b>Select a product</b><span>Available quantity and unit will appear here.</span></div><label>Wasted quantity<input type="number" name="quantity" inputmode="decimal" min="0.001" step="0.001" placeholder="0" required></label><label>Reason<select name="reason"><option>Spoiled</option><option>Expired</option><option>Damaged</option><option>Preparation loss</option><option>Quality issue</option><option>Accidental damage</option><option>Other</option></select></label><label class="full">Note (optional)<textarea name="notes" rows="2" placeholder="Add a short note only if needed"></textarea></label></div>
<button class="btn primary wastage-submit" type="submit" data-wastage-submit disabled><i data-icon="trash"></i>Save wastage & update stock</button></form></article>
<article class="card table-card wastage-history"><div class="table-toolbar"><div><b>Recent wastage</b><small style="display:block;color:var(--muted);margin-top:4px">Latest 30 stock deductions</small></div><input placeholder="Search history…" data-table-search></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Date</th><th>Branch / Brand</th><th>Reason</th><th>Entered by</th><th>Reference</th></tr></thead><tbody><?php foreach($history as $row):?><tr><td data-label="Product"><b><?=e($row['product'])?></b></td><td data-label="Quantity"><b><?=number_format($row['quantity'],3).' '.e($row['symbol'])?></b></td><td data-label="Date"><?=date('d M Y',strtotime($row['wastage_date']))?></td><td data-label="Branch / Brand"><?=e($row['branch'])?> · <?=e($row['brand'])?></td><td data-label="Reason"><span class="status pending"><?=e($row['reason'])?></span></td><td data-label="Entered by"><?=e($row['entered_by'])?></td><td data-label="Reference"><?=e($row['reference_no'])?></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="7"><div class="empty"><div class="empty-icon"><i data-icon="trash"></i></div>No wastage has been recorded.</div></td></tr><?php endif;?></tbody></table></div></article><?php render_footer('wastage');
